@Bean
IntegrationFlow orders(MessageChannel eu, MessageChannel review, MessageChannel rest) {
    return IntegrationFlow.from("orders")
        .route(Order.class, o -> o.region().equals("EU") ? "eu"
                         : o.amount().compareTo(BigDecimal.valueOf(10_000)) > 0 ? "review"
                         : "rest")           // "rest" is the explicit fallback
        .get();
}

